SELECT t_out.material_name name, SUM ( t_out.actual_count ) total FROM t_out_order_detail t_out LEFT JOIN base_material b ON t_out.material_code = b.material_code
and b.material_storage_area = #{material_storage_area}
GROUP BY t_out.material_name ORDER BY total DESC LIMIT 7

SELECT t_in.material_name name, SUM ( t_in.actual_count ) total FROM t_in_order_detail t_in LEFT JOIN base_material b ON t_in.material_code = b.material_code
and b.material_storage_area = #{material_storage_area}
GROUP BY t_in.material_name ORDER BY total DESC LIMIT 7

SELECT COUNT( 1 ) FROM t_task_p
AND task_type LIKE'%入库%'
AND task_type LIKE'%出库%'
and task_type = #{taskType}
AND create_time BETWEEN #{startTime} AND #{endTime}

SELECT COUNT( 1 ) FROM t_task_d
AND task_type LIKE'%入库%'
AND task_type LIKE'%出库%'
AND task_type = #{taskType}
AND create_time BETWEEN #{startTime} AND #{endTime}

SELECT COUNT( 1 ) FROM t_task_x
AND task_type LIKE'%入库%'
AND task_type LIKE'%出库%'
AND task_type = #{taskType}
AND create_time BETWEEN #{startTime} AND #{endTime}

SELECT COUNT( 1 ) FROM t_task_b
AND task_type LIKE'%入库%'
AND task_type LIKE'%出库%'
AND task_type = #{taskType}
AND create_time BETWEEN #{startTime} AND #{endTime}

SELECT "count" ( 1 ) FROM t_location_map
and pallet_code IS NOT NULL
and pallet_code IS NULL
and warehouse = #{material_storage_area}
and status = #{status}

SELECT "sum"(inventory_count) num, b.material_name materialName FROM t_inventory ti LEFT JOIN base_material b ON ti.material_code = b.material_code
and b.material_storage_area = #{material_storage_area}
GROUP BY b.material_name ORDER BY num DESC
LIMIT #{limit}

SELECT status "name", COUNT ( 1 ) "value" FROM t_task_p
and udf02 LIKE concat('%', #{equipment}, '%')
and task_type = #{taskType}
and status = #{status}
AND create_time BETWEEN #{startTime} AND #{endTime}
GROUP BY "name" ORDER BY "value" DESC

SELECT status "name", COUNT ( 1 ) "value" FROM t_task_d
and udf02 LIKE concat('%', #{equipment}, '%')
and task_type = #{taskType}
and status = #{status}
AND create_time BETWEEN #{startTime} AND #{endTime}
GROUP BY "name" ORDER BY "value" DESC

SELECT status "name", COUNT ( 1 ) "value" FROM t_task_x
and udf02 LIKE concat('%', #{equipment}, '%')
and task_type = #{taskType}
and status = #{status}
AND create_time BETWEEN #{startTime} AND #{endTime}
GROUP BY "name" ORDER BY "value" DESC

